/* ============================================================
   src/locale-boot.tpl.js — the body of the generated locales.boot.js.

   Not transpiled: build.mjs copies it verbatim, so it is plain ES5-era script,
   not JSX and not a module.

   build.mjs writes __OFFIQA_LOCALE_META__ and __OFFIQA_TPL_PATTERNS__ above
   this, then appends this file verbatim. Edit here, never in locales.boot.js.

   Its whole job is to load ONE language file instead of all of them. That has
   to happen before anything else runs, because strings are captured in
   top-level constants all over the bundle — by the time app.core.js executes,
   window.t must already be answering in the right language.

   document.write is the mechanism, deliberately. A parser-inserted script that
   writes a <script src> puts it into the parser's stream immediately after
   itself, so it loads and runs before the next tag in the page — which is
   exactly the sequencing a plain <script src="locales.js"> used to give us for
   free. The alternatives do not hold: a script-injected tag (even async=false)
   is not ordered against parser-inserted ones, and a synchronous XHR blocks
   the same thread while being deprecated on top. Chrome's document.write
   intervention only ever applied to cross-origin scripts on slow connections;
   every one of ours is same-origin and on disk.
   ============================================================ */
/* How a lazy string group gets back into the dictionary. Each
   strings.<group>.<code>.js is one call to this; chunk-loader.jsx loads them
   ahead of the chunk that needs them, because a chunk is free to capture a
   string in a top-level constant and several do.

   Defined here rather than in i18n.js so it exists before anything can call it,
   and so a surface that ships strings without the i18n runtime still merges. */
window.__OFFIQA_STRINGS__ = function (code, add) {
  var L = window.__OFFIQA_LOCALES__ || (window.__OFFIQA_LOCALES__ = {});
  var into = L[code] || (L[code] = {});
  (function merge(target, src) {
    for (var k in src) {
      if (!Object.prototype.hasOwnProperty.call(src, k)) continue;
      var v = src[k];
      var deep = v && typeof v === "object" && !Array.isArray(v) &&
                 target[k] && typeof target[k] === "object" && !Array.isArray(target[k]);
      if (deep) merge(target[k], v);
      else target[k] = v;   // a kept leaf already sitting here is never in `add`
    }
  })(into, add);
};

(function () {
  "use strict";

  var META = window.__OFFIQA_LOCALE_META__ || {};
  var FALLBACK = "en";

  /* Use an explicit saved preference, otherwise English. Browser locale is not
     an implicit product choice; a shared browser profile need not represent the
     person opening Offiqa. This runs before i18n.js, which reads it back. */
  var code = null;
  try {
    var stored = localStorage.getItem("offiqa.locale");
    if (stored && META[stored]) code = stored;
  } catch (e) { /* storage can be blocked; use English below */ }

  if (!code) code = META[FALLBACK] ? FALLBACK : (Object.keys(META)[0] || FALLBACK);

  window.__OFFIQA_LOCALE__ = code;

  /* Carry our own ?v= onto the language file. The PWA packager stamps every
     asset URL in the HTML with a build hash so a CDN treats each deploy as new
     URLs; a file we pull in ourselves is not in the HTML, so it has to inherit
     the stamp the way chunk-loader.jsx does. Bare in the extension, where
     nothing is stamped and nothing is cached across versions. */
  var v = "";
  try {
    v = new URL((document.currentScript && document.currentScript.src) || "", location.href)
      .searchParams.get("v") || "";
  } catch (e) { /* no currentScript (shouldn't happen for a classic script) */ }

  document.write('<script src="locales.' + code + '.js' + (v ? "?v=" + v : "") + '"><\/script>');
})();
